            #:: Spawn the targetable version of Manaetic Behemoth in place
            quest::spawn2(206074,0,0,$x,$y,$z,0);
            #:: Depop the untargetable version of Manaetic Behemoth with respawn timer active.
            quest::depop_withtimer();
        }
